function fewestSquares(n: number): number {
  const best = new Array(n + 1).fill(Infinity);
  best[0] = 0;
  for (let i = 1; i <= n; i++) {
    for (let j = 1; j * j <= i; j++) {
      best[i] = Math.min(best[i], best[i - j * j] + 1);
    }
  }
  return best[n];
}

