class Solution:
    def fewestSquares(self, n: int) -> int:
        squares = [j * j for j in range(1, math.isqrt(n) + 1)]
        best = [0] + [n] * n  # n ones always works
        for i in range(1, n + 1):
            for s in squares:
                if s > i:
                    break
                if best[i - s] + 1 < best[i]:
                    best[i] = best[i - s] + 1
        return best[n]

