function fewestSquares(n: number): number {
  const seen = new Uint8Array(n + 1);
  let level = [n], steps = 0;
  seen[n] = 1;
  while (level.length) {
    steps++;
    const next: number[] = [];
    for (const rem of level) {
      for (let j = 1; j * j <= rem; j++) {
        const left = rem - j * j;
        if (left === 0) return steps;
        if (!seen[left]) { seen[left] = 1; next.push(left); }
      }
    }
    level = next;
  }
  return -1;
}

