function fewestSquares(n: number): number {
  const isSq = (x: number) => { const r = Math.floor(Math.sqrt(x)); return r * r === x; };
  if (isSq(n)) return 1;
  let m = n;
  while (m % 4 === 0) m /= 4;
  if (m % 8 === 7) return 4;
  for (let j = 1; j * j < n; j++) if (isSq(n - j * j)) return 2;
  return 3;
}

